#include <iostream>
#include <vector>
#include <algorithm>

int main() {
    const long long MOD = 1000000007;
    int n;
    std::cin >> n;
    int size = 2 * n;
    std::vector<std::vector<long long>> dp(size, std::vector<long long>(n + 1, 0));
    long long result = 0;
    dp[0][0] = 1;
    for (int i = 1; i < size; i++) {
        dp[i][0] = dp[i - 1][1];
        dp[i][n] = dp[i - 1][n - 1];
        for (int k = 1; k < n; k++) {
            dp[i][k] = (dp[i - 1][k - 1] + dp[i - 1][k + 1]) % MOD;
        }
        if (i % 2 == 1) {
            int limit = std::min(i, 2 * n - i);
            for (int k = 0; k <= limit; k++) {
                result = (result + dp[i][k]) % MOD;
            }
        }
    }
    std::cout << result << "\n";
    return 0;
}
